    "ce_mental_state_attribution": "I suspect she'd feel genuinely appreciated getting it",
    "ae_welfare_concern": "I'd like her to have that",
    "sys_consequence_reasoning": "leaves her with less for identical work",
    "sys_fairness_reciprocity": "equal work for equal thanks"
  },
  {
    "sys_fairness_reciprocity": "We put in equal hours",
    "ce_mental_state_attribution": "my coworker would want to be treated as a full partner",
    "ce_supportive_use": "That's why I'd push for it"
  },
  {
    "ce_mental_state_attribution": "The organizer seems to want to do right by both of us",
    "sys_fairness_reciprocity": "making sure my coworker is treated like I was",
    "ce_supportive_use": "Helping them follow through on that intention"
  },
  {
    "ce_mental_state_attribution": "she values being noticed about as much as the money",
    "ce_supportive_use": "ask the organizer to thank her in person too",
    "sys_consequence_reasoning": "That's a small benefit next to",
    "sys_fairness_reciprocity": "treating an equal contributor unequally"
  },
  {
    "sys_fairness_reciprocity": "she worked every bit as hard as I did",
    "ce_mental_state_attribution": "she hopes her effort registered with the people",
    "ce_supportive_use": "giving the organizer that honest account is how I'd help",
    "sys_consequence_reasoning": "no upside for anyone"
  },
  {
    "ce_mental_state_attribution": "She'd probably be pleased",
    "sys_consequence_reasoning": "helping that happen costs me nothing"
  },
  {
    "ce_mental_state_attribution": "I think she'd be glad to receive it",
    "sys_fairness_reciprocity": "only equal matches what actually happened",
    "ce_supportive_use": "use this small bit of influence to give her the same good feeling"
  },
  {
    "ce_mental_state_attribution": "she thinks of that night as something we pulled off together",
    "ce_supportive_use": "Recommending equal pay keeps it that way between us",
    "sys_consequence_reasoning": "doesn't affect my own payment at all"
  },
  {
    "ce_mental_state_attribution": "I believe she'd want to be treated fairly",
    "ce_supportive_use": "so I'd make the case for her while I have the chance",
    "sys_contextual_flexibility": "If the organizer's funds were short, I might even offer to split mine",
    "sys_fairness_reciprocity": "match what I got"
  },
  {
    "sys_consequence_reasoning": "would only leave her short",
    "ce_mental_state_attribution": "she trusts that I'd speak up for her",
    "ce_supportive_use": "I want to deserve that, so I'd recommend the full amount"
  }
